{
  "title": "进水接头",
  "synopsis": "广播站突发断电，周野怀疑人为破坏，林岚排查确认是旧接头进水。两人在清理修复中打破隔阂，约定通电后敲三声铜铃报平安。",
  "preview_blurb": "老街广播站突发断电，维修员林岚与主持人周野在黑暗中排查故障，一个关于三声铜铃的约定悄然生根。",
  "scenes": [
    {
      "title": "断电与猜疑",
      "location": "老街广播站",
      "dramatic_goal": "展现突发断电的危机，交代周野的猜疑与林岚的专业冷静，确立排查方向。",
      "lines": [
        {
          "kind": "narration",
          "text": "老街广播站突发断电，黑暗中只剩下急促的呼吸声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "嘶——又烧了？林岚，是不是有人故意剪线？这月都第三回了，街坊们还等着听晚间新闻呢！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别乱猜，拿手电来。照外墙接线盒，光打准点。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "真不是人为？行行行，手电给你。你手没事吧？刚才那火花看着可吓人，别又触电了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "没破皮。别挡光。"
        }
      ]
    },
    {
      "title": "泥水与和解",
      "location": "外墙接线盒旁",
      "dramatic_goal": "通过实际排查确认进水故障，排除人为破坏；两人在递工具与交谈中化解旧怨，建立合作默契。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "看清楚了。全是青苔和泥水，旧接头进水老化，连绝缘胶布都烂了。没人剪线。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "咳……这雨棚漏水也不是一天两天了，怪我，光顾着播音，没提醒你检查外墙。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "递尖嘴钳。现在说这些没用，把泥水擦干，重新做绝缘。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "给。其实王奶奶下午还问我，今晚能不能播老街的旧歌。这广播站，大家心里都惦记着呢。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "……胶布缠紧点。手别抖。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "没抖，我这不是怕你累着嘛。"
        }
      ]
    },
    {
      "title": "推闸与悬音",
      "location": "广播站配电闸前",
      "dramatic_goal": "完成绝缘测试准备推闸，确立敲铃报平安的约定，并在灯亮敲铃前一刻切断声音，留下悬念。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "清理完了。这就推闸？万一再烧一次，主控台可就真报废了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "绝缘测试通过了，阻值正常。能修好。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "那……等会儿通电，我敲三声铜铃给街坊报平安。这老规矩，得你来推闸，我来敲。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "铃拿来。准备。三，二，一。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "灯亮了！我敲了——"
        }
      ]
    }
  ],
  "episode_summary": "林岚与周野排查广播站断电故障，确认外墙接线盒进水老化。两人在共同清理接头的过程中解开旧误会，关系从猜疑转向合作。修复完毕后，周野拿出铜铃约定推闸通电时敲击报平安，但在灯亮的一瞬间，声音戛然而止。",
  "ending_hook": "闸刀推下，灯光亮起，周野举起铜铃准备敲击，却在发声前一刻陷入死寂。",
  "fact_delta": [
    {
      "change": "广播站断电原因确认为外墙旧接头进水老化，排除人为破坏。"
    },
    {
      "change": "外墙接线盒被清理并重新做好绝缘，具备推闸通电条件。"
